.container {
  position: relative;
  width: 50%;
}
.container img {
  width: 100%;
  height: auto;
}

.container .btn {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background-color: #555;
  color: white;
  padding: 12px 24px;
  border: none;
  cursor: pointer;
}
